package synologyui

import (
	"context"
	"crypto/subtle"
	"encoding/json"
	"errors"
	"io"
	"net/http"
	"path/filepath"
	"regexp"
	"strings"
)

// NASSharePreflighter is the existing owning Agent's READ-ONLY local Root
// admission. A verified preflight is not a Root grant or a created Source.
type NASSharePreflighter interface {
	PreflightLocalRoot(context.Context, string) error
}

var nasSelectionID = regexp.MustCompile("^[0-9a-f]{64}$")

// The browser may submit only a session-bound opaque candidate generated by
// GET nas-shares; it never selects the filesystem path or volume itself.
func resolveNASSharePreflight(
	ctx context.Context, root string, key []byte, principal, cookie, host, selection string,
) (string, error) {
	if !nasSelectionID.MatchString(selection) {
		return "", errors.New("invalid NAS candidate identity")
	}
	choices, err := enumerateNASShareChoices(ctx, root, key, principal, cookie, host)
	if err != nil {
		return "", err
	}
	for _, choice := range choices {
		if subtle.ConstantTimeCompare([]byte(choice.SelectionID), []byte(selection)) == 1 {
			return filepath.Join(root, strings.TrimPrefix(choice.Label, "/")), nil
		}
	}
	return "", errors.New("NAS candidate expired or not authorized")
}

// Exactly one JSON key; duplicate, extra or unknown data may not influence a
// local Agent preflight. Root selection must never come from a pathname.
func parseNASSharePreflight(r *http.Request) (string, error) {
	if r == nil || r.URL == nil || r.URL.RawQuery != "" ||
		r.ContentLength < 2 || r.ContentLength > 256 || r.Body == nil {
		return "", errors.New("invalid NAS preflight request")
	}
	dec := json.NewDecoder(io.LimitReader(r.Body, 257))
	first, err := dec.Token()
	if err != nil || first != json.Delim('{') || !dec.More() {
		return "", errors.New("invalid NAS preflight object")
	}
	field, err := dec.Token()
	if err != nil || field != "selection_id" {
		return "", errors.New("invalid NAS preflight field")
	}
	var selection string
	if err := dec.Decode(&selection); err != nil || !nasSelectionID.MatchString(selection) ||
		dec.More() {
		return "", errors.New("invalid NAS selection identity")
	}
	end, err := dec.Token()
	if err != nil || end != json.Delim('}') {
		return "", errors.New("invalid NAS preflight closing token")
	}
	if _, err := dec.Token(); err != io.EOF {
		return "", errors.New("trailing NAS preflight data")
	}
	return selection, nil
}
